-- Hand-written rules -------------------------------------------------------

ALTER TABLE workshop.quote
  ADD CONSTRAINT quote_status_valid CHECK (status IN ('draft', 'issued', 'approved', 'declined', 'superseded')),
  ADD CONSTRAINT quote_revision_positive CHECK (revision > 0),
  ADD CONSTRAINT quote_discount_range CHECK (discount_pct >= 0 AND discount_pct <= 100),
  ADD CONSTRAINT quote_discount_reason CHECK (discount_pct = 0 OR discount_reason IS NOT NULL),
  ADD CONSTRAINT quote_tax_range CHECK (tax_pct IS NULL OR (tax_pct >= 0 AND tax_pct <= 100)),
  ADD CONSTRAINT quote_amounts_nonnegative CHECK (subtotal >= 0 AND discount_amount >= 0 AND tax_amount >= 0 AND net_amount >= 0),
  -- The arithmetic holds on every row: net = subtotal − discount; total = net (+ tax when added).
  ADD CONSTRAINT quote_totals_consistent CHECK (
    net_amount = subtotal - discount_amount
    AND total = CASE WHEN prices_include_tax THEN net_amount ELSE net_amount + tax_amount END),
  -- Issued quotes are numbered, dated and frozen with what they used.
  ADD CONSTRAINT quote_issued_complete CHECK (
    status = 'draft' OR (number IS NOT NULL AND quote_date IS NOT NULL AND issued_at IS NOT NULL AND issued_by IS NOT NULL)),
  ADD CONSTRAINT quote_approved_complete CHECK (
    status <> 'approved' OR (authorized_by_name IS NOT NULL AND authorized_via IN ('in_person', 'phone', 'written')
                             AND decided_at IS NOT NULL AND decided_by IS NOT NULL)),
  ADD CONSTRAINT quote_declined_reason CHECK (status <> 'declined' OR decline_reason IS NOT NULL),
  -- Nobody approves their own discount.
  ADD CONSTRAINT quote_discount_not_self_approved CHECK (discount_approved_by IS NULL OR discount_approved_by <> discount_set_by);

-- One draft and one open (issued, undecided) quote per job at a time.
CREATE UNIQUE INDEX quote_one_draft ON workshop.quote (job_id) WHERE status = 'draft';
CREATE UNIQUE INDEX quote_one_open ON workshop.quote (job_id) WHERE status = 'issued';

ALTER TABLE workshop.quote_line
  ADD CONSTRAINT quote_line_values CHECK (hours > 0 AND rate > 0 AND amount >= 0 AND (override_amount IS NULL OR override_amount >= 0)),
  ADD CONSTRAINT quote_line_override_reason CHECK (override_amount IS NULL OR override_reason IS NOT NULL),
  ADD CONSTRAINT quote_line_amount CHECK (amount = COALESCE(override_amount, round(hours * rate, 2)));

-- Once issued, a quote's figures never change; only its status moves on (issued → approved,
-- declined or superseded), once. Issued quotes and their lines are never deleted.
CREATE OR REPLACE FUNCTION workshop.guard_quote() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.status <> 'draft' THEN RAISE EXCEPTION 'quote_immutable' USING ERRCODE = 'restrict_violation'; END IF;
    RETURN OLD;
  END IF;
  IF OLD.status = 'draft' THEN
    IF NEW.status NOT IN ('draft', 'issued') THEN
      RAISE EXCEPTION 'quote_not_issued' USING ERRCODE = 'restrict_violation';
    END IF;
    RETURN NEW;
  END IF;
  IF OLD.status <> 'issued' OR NEW.status NOT IN ('approved', 'declined', 'superseded')
     OR (NEW.subtotal, NEW.discount_amount, NEW.net_amount, NEW.tax_amount, NEW.total, NEW.discount_pct,
         NEW.tax_pct, NEW.prices_include_tax, NEW.number, NEW.quote_date, NEW.job_id)
        IS DISTINCT FROM
        (OLD.subtotal, OLD.discount_amount, OLD.net_amount, OLD.tax_amount, OLD.total, OLD.discount_pct,
         OLD.tax_pct, OLD.prices_include_tax, OLD.number, OLD.quote_date, OLD.job_id) THEN
    RAISE EXCEPTION 'quote_immutable' USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER quote_guard BEFORE UPDATE OR DELETE ON workshop.quote
  FOR EACH ROW EXECUTE FUNCTION workshop.guard_quote();

CREATE OR REPLACE FUNCTION workshop.guard_quote_line() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  st text;
BEGIN
  SELECT status INTO st FROM workshop.quote WHERE id = COALESCE(NEW.quote_id, OLD.quote_id);
  -- Deleting the whole draft (cascade) or editing a draft's lines is fine; anything else is not.
  IF st IS NOT NULL AND st <> 'draft' THEN
    RAISE EXCEPTION 'quote_line_immutable' USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN COALESCE(NEW, OLD);
END;
$$;
CREATE TRIGGER quote_line_guard BEFORE INSERT OR UPDATE OR DELETE ON workshop.quote_line
  FOR EACH ROW EXECUTE FUNCTION workshop.guard_quote_line();

